        if hamming_distance(s, s_prime) == k:
            neighbors.append(s_prime)
    return set(neighbors)

def check_indistinguishability(n, k):
    print(f"--- Testing n={n}, k={k} ---")

    # Generate all possible strings S
    all_strings = [''.join(map(str, tuple(it))) for it in itertools.product([0, 1], repeat=n)]

